program='''def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[0 for _ in range(w)] for _ in range(h)]
    bar = next((r for r, row in enumerate(grid) if all(v == 2 for v in row)), None)
    if bar is not None:
        out[bar] = [2] * w
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value != 4:
                continue
            nr = min(r + 1, h - 1)
            out[nr][c] = 4
            if bar is not None and abs(r - bar) == 2:
                dr = -1 if r < bar else 1
                for k in range(1, h):
                    rr, cc1, cc2 = nr + dr * k, c - k, c + k
                    if not (0 <= rr < h):
                        break
                    if 0 <= cc1 < w:
                        out[rr][cc1] = 4
                    if 0 <= cc2 < w:
                        out[rr][cc2] = 4
    return out
'''
p.write_text(program)
exec(compile(program,str(p),'exec'),globals())
